CREATE OR REPLACE FUNCTION public.finalize_streaks_batch() RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$ DECLARE v_user record; v_count integer := 0; BEGIN FOR v_user IN SELECT id FROM public.profiles WHERE anonymized_at IS NULL ORDER BY id LOOP PERFORM public.advance_streak(v_user.id, clock_timestamp()); v_count := v_count + 1; END LOOP; RETURN v_count; END; $$; REVOKE ALL ON FUNCTION public.finalize_streaks_batch() FROM PUBLIC, anon, authenticated; GRANT EXECUTE ON FUNCTION public.finalize_streaks_batch() TO service_role;